wait_for () { local n=0 max=${2:-240}; while ! grep -q '^EXIT=' "$1" 2>/dev/null ; do sleep 5 ; n=$((n+5)); [ "$n" -ge "$max" ] && { echo "still running after ${n}s" ; return 1 ; }; done; grep -n '^EXIT=' "$1"; }
wait_for tmp/gate-batch-32/microgpt-walk.txt; cat tmp/gate-batch-32/microgpt-walk.txt | tail -20; grep -h "VERDICT\|^rc=" tmp/gate-batch-32/microgpt-walk/*.txt

